const cfg = $('Config').first().json;
const requestedCount = Number(cfg.requested_count);
const candidateCap = (Number.isFinite(requestedCount) && requestedCount > 0) ? Math.min(30, Math.max(15, requestedCount * 3)) : 30;
const APPROVED_DOMAINS = ['zakupki.gov.ru','rts-tender.ru','b2b-center.ru','tenderland.ru','tender.pro','vsem-podryad.ru'];
function approvedHost(u){
  if(!u) return false;
  try { const h=new URL(u).hostname.toLowerCase(); return APPROVED_DOMAINS.some(function(d){ return h===d || h.endsWith('.'+d); }); }
  catch(e){ return false; }
}
function normalizeUrl(u){
  if(!u) return '';
  let s=u.trim();
  try {
    const p=new URL(s);
    p.hostname=p.hostname.toLowerCase();
    p.hash='';
    if(p.pathname.endsWith('/')) p.pathname=p.pathname.slice(0,-1);
    s=p.href;
  } catch(e){ s=s.replace(/#.*$/,''); }
  return s;
}
const urls=new Set();
const items=[];
const inputItems=$input.all()||[];
for(const item of inputItems){
  if(!item||!item.json) continue;
  const j=item.json;
  const organic=j.organic||[];
  const results=j.results||[];
  for(const o of organic){
    const link=o.link;
    if(!link) continue;
    if(!approvedHost(link)) continue;
    if(link.includes('youtube.com')||link.includes('instagram.com')||link.includes('facebook.com')) continue;
    const key=normalizeUrl(link);
    if(!key||urls.has(key)) continue;
    urls.add(key);
    items.push({json:{url:link,title:o.title||'',snippet:o.snippet||'',job_id:cfg.job_id,source:'serper'}});
  }
  for(const r of results){
    const link=r.url;
    if(!link) continue;
    if(link.includes('youtube.com')||link.includes('instagram.com')) continue;
    const key=normalizeUrl(link);
    if(!key||urls.has(key)) continue;
    urls.add(key);
    items.push({json:{url:link,title:r.title||'',snippet:r.content||r.snippet||'',job_id:cfg.job_id,source:'tavily'}});
  }
}
const capped=items.slice(0,candidateCap);
return capped.length>0?capped:[{json:{skip:true}}];

const item = $input.first();
const cfg = $('Config').first().json;
const ev = $('Normalize Evidence').item.json;
function isTrue(v){return v===true||v==='true'||v==='TRUE';}
function hasText(v){return v!=null && String(v).trim()!=='';}
function normFull(s){if(s==null)return '';let t=String(s);try{t=t.normalize('NFKC');}catch(e){}t=t.replace(/<[^>]+>/g,' ');t=Array.from(t).filter(function(ch){const c=ch.codePointAt(0);return c>=32||c===9||c===10||c===13;}).join('');return t.replace(/\s+/g,' ').trim();}
function validYMD(v){if(!/^\d{4}-\d{2}-\d{2}$/.test(String(v||'')))return false;const p=String(v).split('-').map(Number);const y=p[0],m=p[1],d=p[2];const dt=new Date(Date.UTC(y,m-1,d));return dt.getUTCFullYear()===y&&dt.getUTCMonth()+1===m&&dt.getUTCDate()===d;}
function ucSlice(s,n){return Array.from(s).slice(0,n).join('');}
let p={};
try{
  const raw=item && item.json ? (item.json.choices?.[0]?.message?.content || '{}') : '{}';
  const clean=raw.replace(/```json/gi,'').replace(/```/g,'').trim();
  p=JSON.parse(clean);
}catch(e){p={};}
const ctx={url:ev.url||'',title:ev.title||'',job_id:ev.job_id||cfg.job_id||''};
const pageType=(p.page_type||'UNKNOWN');
const evidenceStatus=ev.evidence_status||'SNIPPET_ONLY';
const sourceText=normFull(ev.evidence_text||'');
function verifiedEvidence(v){let q=normFull(v);if(!q)return '';q=ucSlice(q,250);return sourceText.includes(q)?q:'';}
const vTenderNumberEv=verifiedEvidence(p.tender_number_evidence);
const vCustomerEv=verifiedEvidence(p.customer_evidence);
const vBudgetEv=verifiedEvidence(p.budget_evidence);
const vDeadlineEv=verifiedEvidence(p.deadline_evidence);
const vRegionEv=verifiedEvidence(p.region_evidence);
const vServiceEv=verifiedEvidence(p.service_evidence);
const vFreshnessEv=verifiedEvidence(p.freshness_evidence);
const vContactNameEv=verifiedEvidence(p.contact_name_evidence);
const vContactPhoneEv=verifiedEvidence(p.contact_phone_evidence);
const vContactEmailEv=verifiedEvidence(p.contact_email_evidence);
const tenderNumber=(hasText(p.tender_number)&&hasText(vTenderNumberEv))?p.tender_number:null;
const customer=(hasText(p.customer)&&hasText(vCustomerEv))?p.customer:null;
let budget=null;
if(p.budget!=null && Number.isFinite(Number(p.budget)) && Number(p.budget)>0 && hasText(vBudgetEv)){
  budget=Number(p.budget);
}
const deadline=(validYMD(p.deadline)&&hasText(vDeadlineEv))?p.deadline:null;
const region=(hasText(p.region)&&hasText(vRegionEv))?p.region:null;
const contact_name=(hasText(p.contact_name)&&hasText(vContactNameEv))?p.contact_name:null;
const contact_phone=(hasText(p.contact_phone)&&hasText(vContactPhoneEv))?p.contact_phone:null;
const contact_email=(hasText(p.contact_email)&&hasText(vContactEmailEv))?p.contact_email:null;
let regionStatus='UNKNOWN';
const rs=(p.region_status||'');
if(rs==='MATCH' && hasText(region) && hasText(vRegionEv)) regionStatus='MATCH';
else if(rs==='MISMATCH' && hasText(region) && hasText(vRegionEv)) regionStatus='MISMATCH';
else regionStatus='UNKNOWN';
let serviceMatch=null;
const sm=p.service_match;
if(sm===true && hasText(vServiceEv)) serviceMatch=true;
else if(sm===false && hasText(vServiceEv)) serviceMatch=false;
else serviceMatch=null;
function freshnessStatus(){
  if(deadline){
    if(deadline>=cfg.verification_date) return 'CURRENT';
    return 'EXPIRED';
  }
  if(p.freshness_explicit_signal==='current' && hasText(vFreshnessEv)) return 'CURRENT';
  if(p.freshness_explicit_signal==='expired' && hasText(vFreshnessEv)) return 'EXPIRED';
  return 'UNKNOWN';
}
const freshStatus=freshnessStatus();
const frags=[vRegionEv,vServiceEv,vFreshnessEv,vTenderNumberEv,vCustomerEv,vBudgetEv,vDeadlineEv].filter(function(f){return hasText(f);});
const uniq=[];const seen={};
for(const f of frags){if(!seen[f]){seen[f]=true;uniq.push(f);}}
const sourceExcerpt=ucSlice(uniq.slice(0,3).join(' | '),800);
function atomicStatus(){
  if(['CATEGORY','LISTING','SEARCH_PAGE','ARTICLE'].includes(pageType)) return 'NON_ATOMIC';
  if(pageType==='UNKNOWN') return 'UNKNOWN';
  if(pageType==='ATOMIC_TENDER'){
    const urlOk=/^https?:\/\//i.test(ctx.url);
    const evOk=['FULL_PAGE','PROVIDER_CONTENT'].includes(evidenceStatus);
    const excOk=hasText(sourceExcerpt);
    if(!(urlOk&&evOk&&excOk)) return 'UNKNOWN';
    const ruleA=(tenderNumber!=null && hasText(vTenderNumberEv));
    if(ruleA) return 'ATOMIC_TENDER';
    let anchors=0;
    if(customer!=null && hasText(vCustomerEv)) anchors++;
    if(budget!=null && hasText(vBudgetEv)) anchors++;
    if(deadline!=null && hasText(vDeadlineEv)) anchors++;
    if(anchors>=2) return 'ATOMIC_TENDER';
    return 'UNKNOWN';
  }
  return 'UNKNOWN';
}
const atomStatus=atomicStatus();
function firstFailReason(){
  if(!/^https?:\/\//i.test(ctx.url)) return 'INVALID_URL';
  if(!['FULL_PAGE','PROVIDER_CONTENT'].includes(evidenceStatus)) return 'EVIDENCE_NOT_FULL';
  if(atomStatus!=='ATOMIC_TENDER') return 'NOT_ATOMIC';
  if(pageType!=='ATOMIC_TENDER') return 'PAGE_TYPE_NOT_ATOMIC';
  if(regionStatus!=='MATCH') return 'REGION_NOT_MATCH';
  if(!hasText(region)) return 'REGION_EMPTY';
  if(serviceMatch!==true) return 'SERVICE_NOT_MATCH';
  if(freshStatus!=='CURRENT') return 'NOT_CURRENT';
  if((Number(p.relevance_score)||0)<20) return 'RELEVANCE_LT_20';
  if(!hasText(sourceExcerpt)) return 'SOURCE_EXCERPT_EMPTY';
  if(cfg.budget_filter_explicit===true){
    if(budget==null) return 'BUDGET_GATE';
    const minN=Number(cfg.budget_min);
    const maxN=Number(cfg.budget_max);
    const bmin=Number.isFinite(minN)?minN:0;
    const bmax=Number.isFinite(maxN)?maxN:999999999;
    if(budget<bmin||budget>bmax) return 'BUDGET_GATE';
  }
  return 'ACCEPT';
}
const ffReason=firstFailReason();
function computeQualityDecision(){
  if(!/^https?:\/\//i.test(ctx.url)) return 'REJECT';
  if(!['FULL_PAGE','PROVIDER_CONTENT'].includes(evidenceStatus)) return 'REJECT';
  if(atomStatus!=='ATOMIC_TENDER') return 'REJECT';
  if(pageType!=='ATOMIC_TENDER') return 'REJECT';
  if(regionStatus!=='MATCH') return 'REJECT';
  if(!hasText(region)) return 'REJECT';
  if(serviceMatch!==true) return 'REJECT';
  if(freshStatus!=='CURRENT') return 'REJECT';
  const rel=(Number(p.relevance_score)||0);
  if(rel<20) return 'REJECT';
  if(!hasText(sourceExcerpt)) return 'REJECT';
  if(cfg.budget_filter_explicit===true){
    if(budget==null) return 'REJECT';
    const minN=Number(cfg.budget_min);
    const maxN=Number(cfg.budget_max);
    const bmin=Number.isFinite(minN)?minN:0;
    const bmax=Number.isFinite(maxN)?maxN:999999999;
    if(budget<bmin||budget>bmax) return 'REJECT';
  }
  return 'ACCEPT';
}
const qualityDecision=computeQualityDecision();
const rel=Number(p.relevance_score)||0;
const t=String(ev.title||'').trim();
const title=(hasText(ev.title)&&!/^(вентиляция|тендер|тендеры|закупки)$/i.test(t))?ev.title:'';
return [{ json:{
  tender_id:'tnd_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,10),
  job_id:ctx.job_id,
  platform:ev.platform||'',
  tender_number:tenderNumber,
  title:title,
  budget:budget,
  deadline:deadline,
  url:ctx.url,
  matched_service:p.matched_service||'',
  win_probability:Number(p.win_probability)||0,
  required_prerequisites:'',
  summary:p.summary_ru||ev.snippet||'',
  relevance_score:rel,
  total_score:rel,
  scraped_at:new Date().toISOString(),
  customer:customer,
  region:region,
  contact_name:contact_name,
  contact_phone:contact_phone,
  contact_email:contact_email,
  atomic_status:atomStatus,
  evidence_status:evidenceStatus,
  region_status:regionStatus,
  freshness_status:freshStatus,
  service_match:serviceMatch,
  source_excerpt:sourceExcerpt,
  entity_type:'tender',
  quality_decision:qualityDecision,
  page_type:pageType,
  first_fail_reason:ffReason
} }];

const cfg=$('Config').first().json||{};
const jobId=cfg.job_id||'unknown';
const requestedCount=cfg.requested_count!=null?cfg.requested_count:null;
function isTrue(v){return v===true||v==='true'||v==='TRUE';}
const rows=$input.all().map(function(i){return i.json;});
const accepted=rows.filter(function(r){
  return r.url && /^https?:\/\//i.test(r.url) &&
    r.atomic_status==='ATOMIC_TENDER' &&
    ['FULL_PAGE','PROVIDER_CONTENT'].includes(r.evidence_status) &&
    r.region_status==='MATCH' &&
    r.freshness_status==='CURRENT' &&
    isTrue(r.service_match);
}).length;
let payloadStr='';
try {
  const pnode=$('Build Tender Display Payload');
  if(pnode && pnode.first && pnode.first().json.tender_display_payload_json){
    payloadStr=String(pnode.first().json.tender_display_payload_json);
  }
}catch(e){ payloadStr=''; }
let payload=null;
try { payload=JSON.parse(payloadStr); } catch(e){ payload=null; }
if(payload && payload.schema_version==='tender-display-v1'){
  payload.verified_count=accepted;
  payloadStr=JSON.stringify(payload);
} else {
  payloadStr='';
}
return [{json:{job_id:jobId,entity_type:'tender',accepted_count:accepted,requested_count:requestedCount,tender_display_payload_json:payloadStr}}];

const item = $input.first();
const ctx = item && item.json ? item.json : {};
const cfg = $('Config').first().json;
const ALLOWLIST=['rts-tender.ru','b2b-center.ru','tenderland.ru','tender.pro','zakupki.gov.ru','vsem-podryad.ru'];
function hostnameOf(u){const m=(u||'').match(/^(?:https?:\/\/)?(?:www\.)?([^\/]+)/i);return m?m[1].toLowerCase():'';}
function normalize(s){if(!s)return '';let t=(typeof s==='string'?s:String(s));try{t=t.normalize('NFKC');}catch(e){}t=t.replace(/<[^>]+>/g,' ');t=Array.from(t).filter(function(ch){var c=ch.codePointAt(0);return c>=32||c===9||c===10||c===13;}).join('');return t.replace(/\s+/g,' ').trim();}
function nonWs(s){return String(s||'').replace(/\s/g,'').length;}
const host=hostnameOf(ctx.url);
const inAllowlist=ALLOWLIST.some(function(d){return host===d||host.endsWith('.'+d);});
let fetchedRaw='';
if(item && item.binary && item.binary.fetched_page){
  try{const buf=await this.helpers.getBinaryDataBuffer(0,'fetched_page');fetchedRaw=buf.toString('utf8').replace(/^\uFEFF/,'').trim();}catch(e){fetchedRaw='';}
}
const fullPage=normalize(fetchedRaw);
const providerText=normalize(ctx.snippet||'');
const source=(ctx.source||'').toLowerCase();
let evidence_status,evidence_text;
if(inAllowlist && nonWs(fullPage)>=200){
  evidence_status='FULL_PAGE'; evidence_text=fullPage;
}else if(source==='tavily' && nonWs(providerText)>=200){
  evidence_status='PROVIDER_CONTENT'; evidence_text=providerText;
}else if(inAllowlist){
  evidence_status='FETCH_UNAVAILABLE'; evidence_text=providerText;
}else{
  evidence_status='SNIPPET_ONLY'; evidence_text=providerText;
}
return [{json:{url:ctx.url||'',title:ctx.title||'',snippet:ctx.snippet||'',job_id:ctx.job_id||'',source:ctx.source||'',platform:host,evidence_status:evidence_status,evidence_text:evidence_text,verification_date:cfg.verification_date,service:cfg.service,region:cfg.region,keywords:cfg.keywords}}];

// Prepare Tender Loop Result — bounded normalized envelope per processed candidate.
const item = $input.first();
let enriched = null;
try { if($('Enrich Tender').item && $('Enrich Tender').item.json){ enriched=$('Enrich Tender').item.json; } } catch(e){ enriched=null; }
if(!enriched || typeof enriched !== 'object'){ enriched = (item && item.json) ? item.json : {}; }
function clip(s,n){ s=(s==null)?'':String(s); return Array.from(s).slice(0,n).join(''); }
function normSMF(v){ if(v===true||v==='true'||v==='TRUE') return true; if(v===false||v==='false'||v==='FALSE') return false; return null; }
const url=(enriched.url!=null)?String(enriched.url):'';
const qualityDecision=(enriched.quality_decision!=null)?String(enriched.quality_decision):'REJECT';
let ff=enriched.first_fail_reason;
if(ff==null || String(ff).trim()===''){ ff=(qualityDecision==='ACCEPT')?'ACCEPT':'NOT_VERIFIED_BY_STRICT_GATE'; }
return [{
  json: {
    job_id: clip(enriched.job_id, 100),
    title: clip(enriched.title, 200),
    platform: clip(enriched.platform, 100),
    url: clip(url, 500),
    page_type: clip(enriched.page_type, 40),
    atomic_status: clip(enriched.atomic_status, 40),
    evidence_status: clip(enriched.evidence_status, 40),
    region_status: clip(enriched.region_status, 40),
    freshness_status: clip(enriched.freshness_status, 40),
    service_match: normSMF(enriched.service_match),
    relevance_score: Number(enriched.relevance_score)||0,
    quality_decision: qualityDecision,
    first_fail_reason: clip(ff, 80),
    source_excerpt: clip(enriched.source_excerpt, 300),
    candidate_snippet: clip(enriched.summary, 500),
    region: clip(enriched.region, 200),
    matched_service: clip(enriched.matched_service, 200),
    deadline: clip(enriched.deadline, 40),
    budget: clip((enriched.budget!=null?String(enriched.budget):''), 80),
    contact_name: clip(enriched.contact_name, 200),
    contact_phone: clip(enriched.contact_phone, 100),
    contact_email: clip(enriched.contact_email, 200)
  }
}];

// Build Tender Display Payload — deterministic B/C classification (regex hostname parsing).
const cfg=$('Config').first().json||{};
const jobId=cfg.job_id||'unknown';
function clip(s,n){ s=(s==null)?'':String(s); return Array.from(s).slice(0,n).join(''); }
function hostnameOf(u){ if(!u)return ''; try{ const m=String(u).match(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\/([^\/?#]+)/); let h=m?m[1]:''; h=h.split('@').pop()||''; h=h.split(':')[0]||''; return h.toLowerCase(); }catch(e){ return (function(){ const m2=String(u).match(/^(?:[a-zA-Z][a-zA-Z0-9+.-]*:\/\/)?(?:[^@\/]*@)?([^\/:]+)/); return m2?m2[1].toLowerCase():''; })(); } }
const APPROVED_DOMAINS=['zakupki.gov.ru','rts-tender.ru','b2b-center.ru','tenderland.ru','tender.pro','vsem-podryad.ru'];
function approvedHost(u){ const h=hostnameOf(u); if(!h)return false; return APPROVED_DOMAINS.some(function(d){ return h===d || h.endsWith('.'+d); }); }
function isVsem(u){ const h=hostnameOf(u); return h==='vsem-podryad.ru' || h.endsWith('.vsem-podryad.ru'); }
function isVsemDetail(u){ if(!u)return false; try{ const m=String(u).match(/\/request\/([0-9a-fA-F-]+)/); if(!m)return false; return /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(m[1]); }catch(e){ return false; } }
function normUrl(u){ if(!u)return ''; try{ const m=String(u).match(/^([a-zA-Z][a-zA-Z0-9+.-]*:\/\/[^\/?#]+\/[^?#]*)/); return m?m[1]:String(u).split('#')[0]; }catch(e){ return String(u).split('#')[0]; } }
function bucketSM(v){ if(v===true)return 'TRUE'; if(v===false)return 'FALSE'; return 'UNKNOWN'; }
function normText(s){ let t=String(s==null?'':s); try{t=t.normalize('NFKC');}catch(e){} return t.toLowerCase().replace(/ё/g,'е'); }
function termHit(haystack, termStr){
  if(!haystack||!termStr) return false;
  const hay=normText(haystack);
  const toks=normText(termStr).split(/\s+/).filter(function(t){return t.length>=3;});
  for(let i=0;i<toks.length;i++){ if(hay.indexOf(toks[i])>=0) return true; }
  return false;
}
const envelopes = $input.all().map(function(i){ return i && i.json ? i.json : null; }).filter(function(x){ return x!=null && !x.skip && x.url; });
const ES=['FULL_PAGE','PROVIDER_CONTENT','SNIPPET_ONLY','FETCH_UNAVAILABLE'];
const PT=['ATOMIC_TENDER','CATEGORY','LISTING','SEARCH_PAGE','ARTICLE','UNKNOWN'];
const RS=['MATCH','MISMATCH','UNKNOWN'];
const FS=['CURRENT','EXPIRED','UNKNOWN'];
const diag={
  evidence_status:{FULL_PAGE:0,PROVIDER_CONTENT:0,SNIPPET_ONLY:0,FETCH_UNAVAILABLE:0},
  page_type:{ATOMIC_TENDER:0,CATEGORY:0,LISTING:0,SEARCH_PAGE:0,ARTICLE:0,UNKNOWN:0},
  region_status:{MATCH:0,MISMATCH:0,UNKNOWN:0},
  freshness_status:{CURRENT:0,EXPIRED:0,UNKNOWN:0},
  service_match:{TRUE:0,FALSE:0,UNKNOWN:0},
  first_fail_counts:{INVALID_URL:0,EVIDENCE_NOT_FULL:0,NOT_ATOMIC:0,PAGE_TYPE_NOT_ATOMIC:0,REGION_NOT_MATCH:0,REGION_EMPTY:0,SERVICE_NOT_MATCH:0,NOT_CURRENT:0,RELEVANCE_LT_20:0,SOURCE_EXCERPT_EMPTY:0,BUDGET_GATE:0,ACCEPT:0}
};
let candidates_total=envelopes.length;
let verified_count=0;
const groupB=[];
const groupC=[];
const seen=new Set();
const targetService=(cfg.service!=null)?String(cfg.service):'';
const targetRegion=(cfg.region!=null)?String(cfg.region):'';
for(let i=0;i<envelopes.length;i++){
  const e=envelopes[i];
  const es=(e.evidence_status!=null)?String(e.evidence_status):'SNIPPET_ONLY';
  const pt=(e.page_type!=null)?String(e.page_type):'UNKNOWN';
  const rsv=(e.region_status!=null)?String(e.region_status):'UNKNOWN';
  const fsv=(e.freshness_status!=null)?String(e.freshness_status):'UNKNOWN';
  const smv=bucketSM(e.service_match);
  diag.evidence_status[ES.indexOf(es)>=0?es:'FETCH_UNAVAILABLE']++;
  diag.page_type[PT.indexOf(pt)>=0?pt:'UNKNOWN']++;
  diag.region_status[RS.indexOf(rsv)>=0?rsv:'UNKNOWN']++;
  diag.freshness_status[FS.indexOf(fsv)>=0?fsv:'UNKNOWN']++;
  diag.service_match[smv]++;
  let ff=(e.first_fail_reason!=null)?String(e.first_fail_reason):'NOT_VERIFIED_BY_STRICT_GATE';
  if(ff==='' || ff==='undefined' || ff==='null') ff='NOT_VERIFIED_BY_STRICT_GATE';
  if(!(ff in diag.first_fail_counts)) ff='NOT_VERIFIED_BY_STRICT_GATE';
  if(!(ff in diag.first_fail_counts)) diag.first_fail_counts[ff]=0;
  diag.first_fail_counts[ff]++;
  const qd=(e.quality_decision!=null)?String(e.quality_decision):'REJECT';
  if(qd==='ACCEPT'){ verified_count++; continue; }
  const u=String(e.url||'');
  if(!/^https?:\/\//i.test(u)) continue;
  if(!approvedHost(u)) continue;
  const nurl=normUrl(u);
  if(!nurl||seen.has(nurl)) continue;
  seen.add(nurl);
  const title=clip(e.title,200);
  const src=clip(e.platform,100)||'Не указан';
  const textBlob=(e.title||'')+' '+(e.candidate_snippet||'')+' '+(e.source_excerpt||'')+' '+(e.region||'')+' '+(e.matched_service||'');
  const serviceSupported = (e.service_match===true) || termHit(textBlob, targetService);
  const regionSupported = (rsv==='MATCH') || termHit(textBlob, targetRegion);
  const vsemDetail = isVsem(u) && isVsemDetail(u);
  const fullEvidence = es==='FULL_PAGE' || es==='PROVIDER_CONTENT';
  if(groupB.length<10 && vsemDetail && fullEvidence && title.length>0 && serviceSupported && regionSupported){
    groupB.push({title:title,source:src,url:clip(u,500),excerpt:clip(e.source_excerpt,300),region:clip(e.region,200),matched_service:clip(e.matched_service,200),deadline:clip(e.deadline,40),budget:clip(e.budget,80),contact_name:clip(e.contact_name,200),contact_phone:clip(e.contact_phone,100),contact_email:clip(e.contact_email,200),reason:''});
    continue;
  }
  if(groupC.length<10){
    const reason=(ff && ff!=='ACCEPT')?ff:'NOT_VERIFIED_BY_STRICT_GATE';
    groupC.push({title:title.length>0?title:'Без названия',source:src,url:clip(u,500),reason:clip(reason,160)});
  }
}
const payload={
  schema_version:'tender-display-v1',
  candidates_total:candidates_total,
  verified_count:verified_count,
  commercial_count:groupB.length,
  manual_count:groupC.length,
